module program
  pc : [0..6] init 0;
  x0 : bool init false;
  x1 : bool init false;
  x2 : bool init false;
  [] pc=0 -> 0.438657109:(x0'=true)&(pc'=1) + 0.561342891:(x0'=false)&(pc'=1);
  [] pc=1 -> 0.019125774:(x1'=x0)&(pc'=2) + 0.980874226:(x1'=false)&(pc'=2);
  [] pc=2 -> 0.815197802:(pc'=3) + 0.184802198:(x1'=false)&(pc'=3);
  [] pc=3 -> 0.05086031:(x1'=true)&(x2'=x1)&(pc'=4) + 0.94913969:(x1'=false)&(x2'=false)&(pc'=4);
